-- Ablage (läuft nach rechte-test.sql; Moritz hat dort Bereiche uebersicht, fahrzeuge, personal; Max nichts)
begin; set local role authenticated; select _als('daniel@konto.bad-dashboard.de');
insert into ablage (schluessel, wert, geaendert) values ('bruell:werkzeuge', '[{"id":"w1"}]', 1), ('bm:2026', '{"plan":1}', 1), ('lohn:2026-10', '{}', 1), ('lohn:konten', '{}', 1), ('bruell:widgets', '{"MO":["kalender"]}', 1);
insert into ablage (schluessel, wert) values ('bruell:raster:pk-901', '{}');
select _pruef('Ablage: vom Admin übertragene Anordnung gehört der Person', (select besitzer from ablage where schluessel = 'bruell:raster:pk-901') = 'max@konto.bad-dashboard.de');
select _pruef('Ablage: Admin legt an, Bereiche setzt die DB', (select bereiche from ablage where schluessel = 'bm:2026') = array['monitor']);
do $$ begin insert into ablage (schluessel, wert) values ('irgendwas', 'x'); perform _pruef('Ablage: unbekannter Schlüssel gesperrt', false); exception when others then perform _pruef('Ablage: unbekannter Schlüssel gesperrt', true); end $$;
do $$ begin update ablage set bereiche = array['uebersicht'] where schluessel = 'bm:2026'; perform _pruef('Ablage: Bereiche nicht vom Browser änderbar', (select bereiche from ablage where schluessel = 'bm:2026') = array['monitor']); end $$;
commit;
begin; set local role authenticated; select _als('moritz@konto.bad-dashboard.de');
select _pruef('Ablage: Monteur sieht nur freigegebene (Widgets)', (select array_agg(schluessel order by schluessel) from ablage) = array['bruell:widgets']);
update ablage set wert = 'kaputt' where schluessel = 'bruell:widgets';
insert into ablage (schluessel, wert, geaendert) values ('bruell:raster:MO', '{"bad":{}}', 2);
select _pruef('Ablage: eigene Anordnung speichern', (select besitzer from ablage where schluessel = 'bruell:raster:MO') = 'moritz@konto.bad-dashboard.de');
update ablage set wert = '{"bad":{"x":1}}' where schluessel = 'bruell:raster:MO';
do $$ begin insert into ablage (schluessel, wert) values ('bruell:raster:DB', '{}'); perform _pruef('Ablage: fremde Anordnung gesperrt', false); exception when others then perform _pruef('Ablage: fremde Anordnung gesperrt', true); end $$;
do $$ begin insert into ablage (schluessel, wert) values ('bm:2027', '{}'); perform _pruef('Ablage: Nicht-Admin legt nichts an', false); exception when others then perform _pruef('Ablage: Nicht-Admin legt nichts an', true); end $$;
commit;
select _pruef('Ablage: Widgets unverändert nach Nicht-Admin-Versuch', (select wert from ablage where schluessel = 'bruell:widgets') = '{"MO":["kalender"]}');
select _pruef('Ablage: eigene Anordnung geändert', (select wert from ablage where schluessel = 'bruell:raster:MO') = '{"bad":{"x":1}}');
begin; set local role authenticated; select _als('max@konto.bad-dashboard.de');
select _pruef('Ablage: ohne Freigabe nur eigene Anordnung', (select array_agg(schluessel) from ablage) = array['bruell:raster:pk-901']);
commit;
begin; set local role authenticated; select _als('daniel@konto.bad-dashboard.de');
select konto_bereiche('max@konto.bad-dashboard.de', array['lohn','werkzeuge']);
commit;
begin; set local role authenticated; select _als('max@konto.bad-dashboard.de');
select _pruef('Ablage: Freigabe Lohn + Werkzeuge', (select array_agg(schluessel order by schluessel) from ablage where schluessel not like 'bruell:raster:%') = array['bruell:werkzeuge','lohn:2026-10','lohn:konten']);
select _pruef('Ablage: nur eigene Anordnung lesbar', (select array_agg(schluessel) from ablage where schluessel like 'bruell:raster:%') = array['bruell:raster:pk-901']);
commit;
begin; set local role authenticated; select _als('daniel@konto.bad-dashboard.de');
select _pruef('Ablage: Admin sieht alles inkl. Anordnungen', (select count(*) from ablage) = 7);
commit;
